    elif opt == 'c':
        opts.forced_command = val
    elif opt == 'p':
        opts.ports.append(val)
    elif opt == 'P':
        opts.pidfile = val
    elif opt == 'l':
        opts.bind_interface = val
    elif opt == 'W':
        n = parse_nonnegative_int(val)
        if n is None:
