    if opts.twofactor and opts.disable_password:
        early("-t and -s are incompatible")
    if opts.forced_command is not None:
        log(f"Forced command set to '{opts.forced_command}'")
    if opts.banner is not None:
        try:
            with open(opts.banner, 'rb'):
                pass
        except Exception:
            log(f"Error opening banner file '{opts.banner}'")


