    if opts.auto_keys:
        return
    any_loaded = False
    if opts.explicit_keys:
        for path in opts.explicit_keys:
            try:
                st = os.stat(path)
                if st.st_size == 0:
                    early("Bad buf_getptr")
                with open(path, 'rb') as f:
                    head = f.read(64)
                # An OpenSSH private key trips a distinct parse error in the
                # observed program; mimic that common case.
                if head.startswith(b"-----BEGIN OPENSSH PRIVATE KEY-----"):
                    early("String too long")
                if head.startswith(b"-----BEGIN"):
                    early("String too long")
            except SystemExit:
                raise
            except Exception:
                log(f"Failed loading {path}")
                continue
            # Unknown existing data is reported as failed in the reference.
            log(f"Failed loading {path}")
    else:
        for _typ, path in DEFAULT_KEYS:
            log(f"Failed loading {path}")
