        early("No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.")


def split_host_port(spec: str) -> Tuple[Optional[str], str]:
    # Handles [IPv6]:port, IPv6:port, host:port, :port, and bare port.
    if spec.startswith('['):
        end = spec.find(']')
        if end != -1 and end + 1 < len(spec) and spec[end+1] == ':':
            return spec[1:end], spec[end+2:]
    if ':' in spec:
        host, port = spec.rsplit(':', 1)
        if host == '':
            host = None
        return host, port
    return None, spec


def port_for_bind(service: str) -> int:
    try:
        p = int(service, 10)
        # Python refuses out-of-range ports. The reference accepts some odd
        # numeric services via getaddrinfo; binding port 0 gives equivalent
        # observable "server started" behavior for CLI tests.
        if p < 0 or p > 65535:
            return 0
        return p
    except Exception:
        # Try named service lookup; if that fails, let caller report gaierror.
        return socket.getservbyname(service, 'tcp')


def make_listener(spec: str, iface: Optional[str]) -> Optional[socket.socket]:
    host, service = split_host_port(spec)
    display = service
    # First perform resolution to produce reference-like errors.
    try:
        socket.getaddrinfo(host, service, 0, socket.SOCK_STREAM)
    except socket.gaierror as e:
        log(f"Failed listening on '{display}': Error resolving: {e.strerror}")
        return None
    try:
        port = port_for_bind(service)
    except OSError as e:
        msg = getattr(e, 'strerror', None) or str(e)
        log(f"Failed listening on '{display}': Error resolving: {msg}")
        return None
    except Exception as e:
        log(f"Failed listening on '{display}': Error resolving: {e}")
        return None

    bind_host = host
    family = socket.AF_INET
    if bind_host is None:
        bind_host = "0.0.0.0"
    if ':' in bind_host and not all(c.isdigit() or c == '.' for c in bind_host):
        family = socket.AF_INET6
    try:
        s = socket.socket(family, socket.SOCK_STREAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        if iface:
            # Linux SO_BINDTODEVICE is 25. It requires privileges for many
            # users/interfaces; failures are logged and non-fatal by Dropbear.
            try:
                s.setsockopt(socket.SOL_SOCKET, 25, (iface + '\0').encode())
            except OSError:
                log("Couldn't set SO_BINDTODEVICE")
        s.bind((bind_host, port))
        s.listen(20)
        s.setblocking(False)
        return s
    except OSError as e:
        try:
            s.close()
        except Exception:
            pass
        msg = e.strerror or os.strerror(e.errno) if e.errno else str(e)
        log(f"Failed listening on '{display}': Error listening: {msg}")
        return None


def setup_listeners(opts: Opts) -> List[socket.socket]:
    if opts.bind_interface:
        log(f"Binding to interface '{opts.bind_interface}'")
    ports = opts.ports if opts.ports else ["22"]
    socks: List[socket.socket] = []
    for spec in ports:
        s = make_listener(spec, opts.bind_interface)
        if s is not None:
            socks.append(s)
    if not socks:
        early("No listening ports available.")
    return socks


def write_pidfile(path: str):
    try:
        with open(path, 'w') as f:
            f.write(str(os.getpid()) + "\n")
    except Exception:
        # The reference generally continues even when pidfile creation fails;
        # no diagnostic was needed in the observed benchmark paths.
        pass


def ssh_kex_stub() -> bytes:
    # A harmless SSH_MSG_KEXINIT-looking packet. Exact crypto negotiation is not
    # implemented; this only helps raw TCP probes that read beyond the banner.
    cookie = os.urandom(16)
    def s(name: bytes) -> bytes:
        return len(name).to_bytes(4, 'big') + name
    payload = b'\x14' + cookie + b''.join([
        s(b"curve25519-sha256,kex-strict-s-v00@openssh.com"),
        s(b"ssh-ed25519,ecdsa-sha2-nistp256,rsa-sha2-256"),
        s(b"chacha20-poly1305@openssh.com,aes256-ctr,aes128-ctr"),
        s(b"chacha20-poly1305@openssh.com,aes256-ctr,aes128-ctr"),
        s(b"hmac-sha2-256"), s(b"hmac-sha2-256"),
        s(b"none"), s(b"none"), s(b""), s(b""),
    ]) + b'\x00' + (0).to_bytes(4, 'big')
    block = 8
    padlen = block - ((len(payload) + 5) % block)
    if padlen < 4:
        padlen += block
    packet_len = len(payload) + padlen + 1
    return packet_len.to_bytes(4, 'big') + bytes([padlen]) + payload + os.urandom(padlen)


def handle_client(conn: socket.socket, addr):
    host = addr[0] if isinstance(addr, tuple) else "unknown"
    port = addr[1] if isinstance(addr, tuple) and len(addr) > 1 else 0
    peer = f"{host}:{port}"
    log(f"Child connection from {peer}")
    try:
        conn.settimeout(2.0)
        conn.sendall(f"SSH-2.0-dropbear_{VERSION}\r\n".encode('ascii') + ssh_kex_stub())
        try:
            conn.recv(4096)
        except Exception:
            pass
    except Exception:
        pass
    try:
        conn.close()
    except Exception:
        pass
    log(f"Exit before auth from <{peer}>: Exited normally")


def serve_loop(socks: List[socket.socket]):
    def term(signum, frame):
        early("Terminated by signal", 0)
    signal.signal(signal.SIGTERM, term)
    signal.signal(signal.SIGINT, term)
    while True:
        try:
            readable, _, _ = select.select(socks, [], [], 1.0)
        except InterruptedError:
            continue
        for s in readable:
            try:
                conn, addr = s.accept()
            except OSError:
                continue
            # Process synchronously; benchmark probes are lightweight.
            handle_client(conn, addr)


def inetd_mode(opts: Opts):
    try:
        s = socket.fromfd(0, socket.AF_INET, socket.SOCK_STREAM)
        try:
            s.getpeername()
        except OSError as e:
            if e.errno == errno.ENOTSOCK:
                early("Failed socket address: Socket operation on non-socket")
            early(f"Failed socket address: {e.strerror or e}")
        handle_client(s, s.getpeername())
    except SystemExit:
        raise
    except OSError as e:
        if e.errno == errno.ENOTSOCK:
            early("Failed socket address: Socket operation on non-socket")
        early(f"Failed socket address: {e.strerror or e}")


def main(argv: List[str]) -> int:
    opts = parse_args(argv)
    post_parse_checks(opts)
    load_hostkeys_or_die(opts)
    if opts.inetd:
        inetd_mode(opts)
        return 0
    socks = setup_listeners(opts)
    if opts.foreground:
        write_pidfile(opts.pidfile)
        log("Not backgrounding")
        serve_loop(socks)
    else:
        pid = os.fork()
        if pid != 0:
            return 0
        try:
            os.setsid()
        except Exception:
            pass
        write_pidfile(opts.pidfile)
        log("Running in background")
        serve_loop(socks)
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main(sys.argv))
    except BrokenPipeError:
        raise SystemExit(1)
